node --input-type=module <<'NODE'
import fs from 'node:fs';
import { artifactDigest, sha256 } from './scripts/remediation/board.mjs';
const tracker=JSON.parse(fs.readFileSync('docs/remediation/tracker.json','utf8'));
const task=tracker.tasks.find(x=>x.id==='W06.04');
const old=task.acceptance_history.find(x=>x.artifact?.digest==='03b7b3657aab005204abce531a282289d4a045b3d7b1a60e2562cd572ef1b911').artifact;
const pins=old.files.map(file=>({...file,current_sha256:sha256(fs.readFileSync(file.path)),matches:sha256(fs.readFileSync(file.path))===file.sha256}));
const compilerPath='docs/remediation/evidence/W06.05/worker-checks.json';
const proof=JSON.parse(fs.readFileSync(compilerPath,'utf8'));
console.log(JSON.stringify({at:new Date().toISOString(),task_state:task.state,historical_artifact:old,historical_digest_valid:artifactDigest(old)===old.digest,pins,compiler_proof:{path:compilerPath,sha256:sha256(fs.readFileSync(compilerPath)),keys:Object.keys(proof),checks:proof.checks?.filter(x=>x.id?.includes('noEmit'))}},null,2));
NODE

